231	function hasAutoMeasureEvent(eventData: any) {
232	  return Boolean(
233	    eventData?.condition?.conditionList?.some((group: any) =>
234	      group.ruleList?.some(
235	        (rule: any) =>
236	          rule.factoryTagCode !== null &&
237	          rule.factoryTagCode !== undefined &&
238	          rule.factoryTagCode !== "" &&
239	          rule.conditionRule !== null &&
240	          rule.conditionRule !== undefined &&
241	          rule.conditionRule !== "" &&
242	          rule.conditionValue !== null &&
243	          rule.conditionValue !== undefined &&
244	          rule.conditionValue !== "",
245	      ),
246	    ),
247	  );
248	}
249	
250	function normalizeAutoMeasureEvent(eventData: any) {
251	  if (!hasAutoMeasureEvent(eventData)) return null;
252	  eventData.condition.conditionList = eventData.condition.conditionList.map(
253	    (group: any) => {
254	      return {
255	        ...group,
256	        ruleList: (group.ruleList || []).map((rule: any) => {
257	          return {
258	            ...rule,
259	            conditionValue: String(rule.conditionValue),
260	          };
261	        }),
262	      };
263	    },
264	  );
265	  return eventData;
266	}
267	
268	function normalizeProcessFeedData(sendData: any) {
269	  sendData.operateList?.forEach((operate: any) => {
270	    Object.values(operate.taskMsgMap || {}).forEach((taskMsg: any) => {
271	      const feedData = taskMsg?.monitorOperateParam?.feedData;
272	      if (!feedData) return;
273	
274	      const feedWay = Number(feedData.feedWay);
275	      // 提交工艺节点前剔除旧事件ID和后端回显说明字段。
276	      delete feedData.feedStartRuleGroup;
277	      delete feedData.feedEndRuleGroup;
278	      delete feedData.startEventId;
279	      delete feedData.endEventId;
280	      delete feedData.acquireEventId;
281	      delete feedData.measureFormula;
282	
283	      if (![1, 2, 3, 5].includes(feedWay)) {
284	        feedData.startEvent = null;
285	        feedData.endEvent = null;
286	        return;
287	      }
288	
289	      if (feedWay === 3) {
290	        feedData.feedTagCode = null;
291	        feedData.inventoryId = null;
292	      } else {
293	        feedData.stId = null;
294	      }
295	
296	      feedData.startEvent = normalizeAutoMeasureEvent(feedData.startEvent);
297	      feedData.endEvent =
298	        feedWay === 5 ? null : normalizeAutoMeasureEvent(feedData.endEvent);
299	    });
300	  });
301	}
302	
303	function normalizeProcessAlarmData(sendData: any) {
304	  sendData.operateList?.forEach((operate: any) => {
305	    Object.values(operate.taskMsgMap || {}).forEach((taskMsg: any) => {
306	      if (taskMsg?.alarmConfigVersion !== 1 || !taskMsg?.alarmParam) return;
307	
308	      delete taskMsg.alarmParam.alarmRule;
309	      taskMsg.alarmParam.rules = (taskMsg.alarmParam.rules || []).map(
310	        (rule: any) => ({
311	          ...rule,
312	          conditions: (rule.conditions || []).map((condition: any) => ({
313	            ...condition,
314	            threshold: String(condition.threshold ?? ""),
315	          })),
316	          notifyUsers: msgNotifyToNotifyUsers(
317	            taskMsg.alarmParam.msgNotify,
318	          ).map((notifyUser) => ({ ...notifyUser })),
319	        }),
320	      );
321	    });
322	  });
323	}
324	
325	function restoreProcessAlarmNotify(operateList: any[]) {
326	  operateList?.forEach((operate: any) => {
327	    Object.values(operate.taskMsgMap || {}).forEach((taskMsg: any) => {
328	      const alarmParam = taskMsg?.alarmParam;
329	      const firstRule = alarmParam?.rules?.[0];
330	      if (taskMsg?.alarmConfigVersion !== 1 || !firstRule?.notifyUsers) return;
331	
332	      alarmParam.msgNotify = {
333	        ...(alarmParam.msgNotify || {}),
334	        ...notifyUsersToMsgNotify(firstRule.notifyUsers),
335	      };
336	    });
337	  });
338	}
