415	async function exportBpmnAsImages(dataJson: any) {
416	  // 一定要有个容器 并且容器又宽高 不能隐藏
417	  const container = document.getElementById("bpmn-container") as HTMLElement;
418	
419	  const bpmnViewer = new BpmnJS({
420	    container: container, // 设置容器
421	  });
422	  // const bpmnViewer = new BpmnJS();
423	  const imgList: any[] = [];
424	  // 循环遍历每个 BPMN XML
425	  for (const operate of data.operateList) {
426	    try {
427	      // 导入 BPMN XML
428	      await bpmnViewer.importXML(operate?.xml);
429	
430	      const { svg } = await bpmnViewer.saveSVG();
431	
432	      // 使用 DOMParser 解析 SVG 字符串
433	      const parser = new DOMParser();
434	      const svgDoc = parser.parseFromString(svg, "image/svg+xml");
435	
436	      // 获取到 SVG 元素
437	      const svgElement = svgDoc.documentElement;
438	
439	      // 修改 SVG 的背景色
440	      svgElement.setAttribute("style", "background-color: #fff;");
441	
442	      // 获取修改后的 SVG 字符串
443	      const updatedSvg = new XMLSerializer().serializeToString(svgDoc);
444	
445	      // console.log(svg);
446	
447	      await svgToImage(updatedSvg, imgList, operate);
448	    } catch (err) {
449	      console.error("Error exporting BPMN:", err);
450	    }
451	  }
452	
453	  let httpStr: string = "";
454	  if (import.meta.env.VITE_ENV === "production")
455	    httpStr = window.location.origin;
456	  else httpStr = import.meta.env.VITE_APP_BASE_URL;
457	
458	  const sendData = {
459	    postGetAction: props.id
460	      ? `${httpStr}/api/process/editProcessStep`
461	      : `${httpStr}/api/process/addProcessStep`, //请求接口地址
462	    type: "1", // 1为工艺流程审批
463	    postGetType: "post", // 请求类型（post、get）
464	    dataJson, // 原数据
465	    urlJson: {
466	      bomIdList: data.bomIdList,
467	      processName: data.process.processName,
468	      imgList,
469	    }, // 组装后的数据
470	  };
471	
472	  const res = await sageOp(sendData);
473	  if (res?.code === 200) {
474	    message.success(res.msg || res.msg);
475	    emit("update:modelValue", false);
476	    emit("getData");
477	  }
478	}
479	
