{"content": "<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="utf-8" />
    <title>a-select fieldNames 验证</title>
  </head>
  <body>
    <div id="app"></div>
    <script type="module">
      import { createApp, h, ref, computed } from "vue";
      import Antd from "ant-design-vue";
      import "ant-design-vue/dist/reset.css";

      // 与 ConfigDrawer.vue 中一致的选项加工逻辑
      const normalizeMaterialOption = (item) => {
        const materialName = item?.maName ?? "";
        const materialCode = item?.maCode ?? item?.materialCode ?? "";
        const label =
          materialName && materialCode
            ? `${materialName}（${materialCode}）`
            : materialName || String(materialCode || "");
        return {
          ...item,
          label,
          searchText: `${materialName} ${materialCode}`.toLowerCase(),
        };
      };

      const filterOption = (input, option, name = "label") => {
        return String(option?.[name] ?? "")
          .toLowerCase()
          .includes(input.toLowerCase());
      };

      const raw = ref([
        { materialProductId: 1, maId: 1, maName: "4-4二甲苯", maCode: "BHR2540" },
        { materialProductId: 2, maId: 2, maName: "亚硫酸钠", maCode: "BHO340-2" },
        { materialProductId: 3, maId: 3, maName: "亚硫酸钠", maCode: "BHO340-3" },
        { materialProductId: 4, maId: 4, maName: "水", maCode: "" },
      ]);
      const materialOptions = computed(() => raw.value.map(normalizeMaterialOption));
      const materialId = ref(2);

      const App = {
        setup() {
          return () =>
            h("div", { style: "padding:24px;width:600px" }, [
              h(Antd.Select, {
                class: "material-select",
                open: true,
                showSearch: true,
                allowClear: true,
                value: materialId.value,
                options: materialOptions.value,
                fieldNames: { label: "label", value: "materialProductId" },
                filterOption: (input, option) =>
                  filterOption(input, option, "searchText"),
                "onUpdate:value": (v) => (materialId.value = v),
              }),
            ]);
        },
      };

      createApp(App).use(Antd).mount("#app");
    </script>
  </body>
</html>
