{"content": "// 扫描 src 下所有 .vue / .ts 文件的语法错误（含未被任何入口引用的页面文件，构建不会编译到它们）
import fs from "node:fs";
import path from "node:path";
import { parse, compileScript, compileTemplate } from "vue/compiler-sfc";

const root = path.resolve("src");
const files = [];
const walk = (dir) => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "node_modules" || entry.name === "svg") continue;
      walk(full);
    } else if (/\.(vue|ts|tsx)$/.test(entry.name) && !entry.name.endsWith(".d.ts")) {
      files.push(full);
    }
  }
};
walk(root);

const vueErrors = [];
for (const file of files.filter((f) => f.endsWith(".vue"))) {
  const source = fs.readFileSync(file, "utf8");
  const rel = path.relative(process.cwd(), file);
  const { descriptor, errors } = parse(source, { filename: file });
  if (errors.length) {
    vueErrors.push([rel, "SFC parse", errors.map((e) => e.message || String(e))]);
  }
  const id = "scan";
  try {
    if (descriptor.scriptSetup || descriptor.script) {
      compileScript(descriptor, { id });
    }
  } catch (e) {
    vueErrors.push([rel, "script", [String(e.message || e)]]);
  }
  if (descriptor.template) {
    const res = compileTemplate({
      source: descriptor.template.content,
      filename: file,
      id,
    });
    if (res.errors?.length) {
      vueErrors.push([
        rel,
        "template",
        res.errors.map((e) => e.message || String(e)),
      ]);
    }
  }
}

console.log(`扫描 vue 文件 ${files.filter((f) => f.endsWith(".vue")).length} 个`);
if (!vueErrors.length) {
  console.log("✅ 没有语法/编译错误");
} else {
  console.log(`❌ ${vueErrors.length} 个文件有问题：`);
  for (const [rel, stage, msgs] of vueErrors) {
    console.log(`- ${rel} [${stage}] ${msgs.join(" | ")}`);
  }
}
