{"content": "import { createApp, computed, h, ref } from "vue";
import { Select } from "ant-design-vue";
import "ant-design-vue/dist/reset.css";

// ===== 与 ConfigDrawer.vue 中的实现保持一致 =====
const normalizeMaterialOption = (item) => {
  const materialName = item?.maName ?? "";
  const materialCode = item?.maCode ?? item?.materialCode ?? "";
  const label =
    materialName && materialCode
      ? `${materialName}（${materialCode}）`
      : materialName || String(materialCode || "");

  return {
    ...item,
    label,
    searchText: `${materialName} ${materialCode}`.toLowerCase(),
  };
};

const filterOption = (input, option, name = "label") => {
  return String(option?.[name] ?? "")
    .toLowerCase()
    .includes(input.toLowerCase());
};
// ==============================================

// 模拟 findMaterialByBomIds 的返回（物料名取自设计稿候选列表）
const rawOptions = [
  { materialProductId: "p1", maId: 1, maName: "4-4二甲苯", maCode: "M-10001" },
  { materialProductId: "p2", maId: 2, maName: "BHR2540", maCode: "BHR2540" },
  { materialProductId: "p3", maId: 3, maName: "BHO340-2", maCode: "BHO340-2" },
  { materialProductId: "p4", maId: 4, maName: "水", maCode: "W-0001" },
  { materialProductId: "p5", maId: 5, maName: "亚硫酸钠", maCode: "S-2001" },
  { materialProductId: "p6", maId: 6, maName: "高岭土" },
];

const App = {
  setup() {
    const selected = ref(undefined);
    const materialOptions = computed(() =>
      rawOptions.map(normalizeMaterialOption),
    );
    return { selected, materialOptions };
  },
  render() {
    return h("div", { style: "padding: 24px" }, [
      h(Select, {
        id: "material-select",
        showSearch: true,
        allowClear: true,
        style: "width: 420px",
        placeholder: "请选择物料",
        value: this.selected,
        "onUpdate:value": (v) => {
          this.selected = v;
        },
        options: this.materialOptions,
        filterOption: (input, option) =>
          filterOption(input, option, "searchText"),
        fieldNames: { label: "label", value: "materialProductId" },
      }),
      h("div", { class: "echo" }, [
        "selected value: ",
        h("span", { id: "echo" }, String(this.selected)),
      ]),
    ]);
  },
};

createApp(App).mount("#app");
